+/**
+ * React-style component structure for a standalone HTML document.
+ */
+
+const DeleteDialog = ({ id, onCancel, onConfirm }) => {
+    const dialog = document.createElement('dialog');
+    dialog.id = id;
+    dialog.setAttribute('aria-labelledby', `${id}-title`);
+    dialog.setAttribute('aria-describedby', `${id}-description`);
+
+    dialog.innerHTML = `
+        <div class="dialog-content">
+            <h2 id="${id}-title">Delete Image?</h2>
+            <p id="${id}-description">Are you sure you want to delete this image from your library? This action cannot be undone.</p>
+            <div class="dialog-actions">
+                <button type="button" class="btn btn-secondary" id="${id}-cancel">Cancel</button>
+                <button type="button" class="btn btn-danger" id="${id}-confirm">Delete</button>
+            </div>
+        </div>
+    `;
+
+    // Event listeners
+    dialog.querySelector(`#${id}-cancel`).addEventListener('click', () => {
+        dialog.close('cancel');
+        onCancel();
+    });
+
+    dialog.querySelector(`#${id}-confirm`).addEventListener('click', () => {
+        dialog.close('confirm');
+        onConfirm();
+    });
+
+    // Close on backdrop click
+    dialog.addEventListener('click', (event) => {
+        if (event.target === dialog) {
+            dialog.close('cancel');
+            onCancel();
+        }
+    });
+
+    return dialog;
+};
+
+const ImagePreview = ({ imageUrl, onDeleteClick }) => {
+    const section = document.createElement('main');
+    section.className = 'container';
+
+    section.innerHTML = `
+        <div class="image-card">
+            <img src="${imageUrl}" alt="Preview of your uploaded image" class="image-preview">
+            <button type="button" class="btn btn-danger trigger">Delete Image</button>
+        </div>
+    `;
+
+    section.querySelector('.trigger').addEventListener('click', onDeleteClick);
+
+    return section;
+};
+
+const App = () => {
+    const root = document.getElementById('root');
+    
+    // Placeholder image
+    const imageUrl = 'https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?q=80&w=600&auto=format&fit=crop';
+
+    const handleDeleteClick = () => {
+        const dialog = document.getElementById('confirm-delete-dialog');
+        dialog.showModal();
+        // Focus the cancel button to prevent accidental deletion
+        dialog.querySelector('.btn-secondary').focus();
+    };
+
+    const handleCancel = () => {
+        console.log('Deletion cancelled');
+    };
+
+    const handleConfirm = () => {
+        console.log('Image deleted');
+        // In a real app, we would remove the image from the UI
+        const card = document.querySelector('.image-card');
+        card.innerHTML = '<p style="padding: 2rem;">Image deleted from your library.</p>';
+    };
+
+    // Build the components
+    const preview = ImagePreview({ imageUrl, onDeleteClick: handleDeleteClick });
+    const dialog = DeleteDialog({ 
+        id: 'confirm-delete-dialog', 
+        onCancel: handleCancel, 
+        onConfirm: handleConfirm 
+    });
+
+    root.appendChild(preview);
+    root.appendChild(dialog);
+};
+
+// Initialize the app
+document.addEventListener('DOMContentLoaded', App);
+
