const DeleteDialog = ({ id, onCancel, onConfirm }) => {
    const dialog = document.createElement('dialog');
    dialog.id = id;
    dialog.setAttribute('aria-labelledby', `${id}-title`);
    dialog.setAttribute('aria-describedby', `${id}-description`);

    dialog.innerHTML = `
        <div class="dialog-content">
            <h2 id="${id}-title">Delete Image?</h2>
            <p id="${id}-description">Are you sure you want to delete this image from your library? This action cannot be undone.</p>
            <div class="dialog-actions">
                <button type="button" class="btn btn-secondary" id="${id}-cancel">Cancel</button>
                <button type="button" class="btn btn-danger" id="${id}-confirm">Delete</button>
            </div>
        </div>
    `;

    // Event listeners
    dialog.querySelector(`#${id}-cancel`).addEventListener('click', () => {
        dialog.close('cancel');
        onCancel();
    });

    dialog.querySelector(`#${id}-confirm`).addEventListener('click', () => {
        dialog.close('confirm');
        onConfirm();
    });

    // Close on backdrop click
    dialog.addEventListener('click', (event) => {
        if (event.target === dialog) {
            dialog.close('cancel');
            onCancel();
        }
    });

    return dialog;
};

const ImagePreview = ({ imageUrl, onDeleteClick }) => {
    const main = document.createElement('main');
    main.className = 'container';

    main.innerHTML = `
        <div class="image-card">
            <h2 class="sr-only">Image Preview</h2>
            <img src="${imageUrl}" alt="Abstract purple and blue fluid shapes" class="image-preview">
            <button type="button" class="btn btn-danger trigger">Delete Image</button>
        </div>
    `;

    main.querySelector('.trigger').addEventListener('click', onDeleteClick);

    return main;
};

