        const axeSource = fs.readFileSync(path.join(__dirname, 'node_modules', 'axe-core', 'axe.min.js'), 'utf8');
        await browserPage.addScriptTag({ content: axeSource });
        const results = await browserPage.evaluate(async () => {
            return await window.axe.run();
        });
        console.log(JSON.stringify(results.violations, null, 2));
        if (results.violations.length > 0) process.exit(1);
    } catch (err) {
        console.error(err);
        process.exit(1);
    } finally {
        if (browser) await browser.close();
        if (server) server.close();
    }
})();
